        { title: "Fix Fix Optional Property 9", level: "expert", desc: "Optional property accessed without null check.", bug: "interface Config { name?: string; }\nfunction show(c: Config) {\n  console.log(c.name.uppercase());\n}\nshow({});", solution: "interface Config { name?: string; }\nfunction show(c: Config) {\n  console.log(c.name?.toUpperCase());\n}\nshow({});", test: "true // TS optional" },
        { title: "Fix Fix Array Type 9", level: "expert", desc: "Array type annotation uses wrong syntax.", bug: "let items: Array<string> = ['a', 'b'];\nconsole.log(items);", solution: "let items: string[] = ['a', 'b'];\nconsole.log(items);", test: "true // TS array" },
        { title: "Fix Fix Tuple Type 9", level: "expert", desc: "Tuple declared but accessed with wrong index type.", bug: "let pair: [string, number] = ['age', 30];\nconsole.log(pair[1].toFixed(2));", solution: "let pair: [string, number] = ['age', 30];\nconsole.log(pair[1].toFixed(2));", test: "true // TS tuple" },
        { title: "Fix Fix Enum Value 9", level: "expert", desc: "Enum member accessed without proper namespace.", bug: "enum Color { Red, Green, Blue }\nconsole.log(Color.Red);\nlet c: Color = 'Red';", solution: "enum Color { Red, Green, Blue }\nconsole.log(Color.Red);\nlet c: Color = Color.Red;", test: "true // TS enum" },
        { title: "Fix Fix Type Assertion 9", level: "expert", desc: "Type assertion using wrong syntax.", bug: "let value: any = 'hello';\nlet len: number = (value as string).length;\nconsole.log(len);", solution: "let value: any = 'hello';\nlet len: number = (value as string).length;\nconsole.log(len);", test: "true // TS assertion" },
        { title: "Fix Fix Void Return 9", level: "expert", desc: "Function returning void but returns value.", bug: "function log(msg: string): void {\n  return msg;\n}\nconsole.log(log('test'));", solution: "function log(msg: string): void {\n  console.log(msg);\n}\nlog('test');", test: "true // TS void" },
        { title: "Fix Fix Any vs Unknown 9", level: "expert", desc: "Using any instead of unknown requires type narrowing.", bug: "function safeParse(json: string): unknown {\n  return JSON.parse(json);\n}\nconst data = safeParse('{\"a\":1}');\nconsole.log(data.a);", solution: "function safeParse(json: string): unknown {\n  return JSON.parse(json);\n}\nconst data = safeParse('{\"a\":1}') as Record<string, any>;\nconsole.log(data.a);", test: "true // TS unknown" },
        { title: "Fix Fix Type Annotation 10", level: "expert", desc: "Missing type annotation on function parameter.", bug: "function greet(name) {\n  return 'Hello ' + name;\n}\nconsole.log(greet('Doge'));", solution: "function greet(name: string): string {\n  return 'Hello ' + name;\n}\nconsole.log(greet('Doge'));", test: "true // TS type" },
        { title: "Fix Fix Interface Property 10", level: "expert", desc: "Interface property name doesn't match implementation.", bug: "interface Person { name: string; }\nconst p: Person = { name: 'Doge' };\nconsole.log(p.name);", solution: "interface Person { name: string; }\nconst p: Person = { name: 'Doge' };\nconsole.log(p.name);", test: "true // TS interface" },
        { title: "Fix Fix Union Type 10", level: "expert", desc: "Union type missing pipe symbol.", bug: "function format(id: string | number) {\n  return 'ID: ' + id;\n}\nconsole.log(format(42));\nconsole.log(format('abc'));", solution: "function format(id: string | number) {\n  return 'ID: ' + id;\n}\nconsole.log(format(42));\nconsole.log(format('abc'));", test: "true // TS union" },
        { title: "Fix Fix Optional Property 10", level: "expert", desc: "Optional property accessed without null check.", bug: "interface Config { name?: string; }\nfunction show(c: Config) {\n  console.log(c.name.uppercase());\n}\nshow({});", solution: "interface Config { name?: string; }\nfunction show(c: Config) {\n  console.log(c.name?.toUpperCase());\n}\nshow({});", test: "true // TS optional" },
        { title: "Fix Fix Array Type 10", level: "expert", desc: "Array type annotation uses wrong syntax.", bug: "let items: Array<string> = ['a', 'b'];\nconsole.log(items);", solution: "let items: string[] = ['a', 'b'];\nconsole.log(items);", test: "true // TS array" },
        { title: "Fix Fix Tuple Type 10", level: "expert", desc: "Tuple declared but accessed with wrong index type.", bug: "let pair: [string, number] = ['age', 30];\nconsole.log(pair[1].toFixed(2));", solution: "let pair: [string, number] = ['age', 30];\nconsole.log(pair[1].toFixed(2));", test: "true // TS tuple" },
        { title: "Fix Fix Enum Value 10", level: "expert", desc: "Enum member accessed without proper namespace.", bug: "enum Color { Red, Green, Blue }\nconsole.log(Color.Red);\nlet c: Color = 'Red';", solution: "enum Color { Red, Green, Blue }\nconsole.log(Color.Red);\nlet c: Color = Color.Red;", test: "true // TS enum" },
        { title: "Fix Fix Type Assertion 10", level: "expert", desc: "Type assertion using wrong syntax.", bug: "let value: any = 'hello';\nlet len: number = (value as string).length;\nconsole.log(len);", solution: "let value: any = 'hello';\nlet len: number = (value as string).length;\nconsole.log(len);", test: "true // TS assertion" },
        { title: "Fix Fix Void Return 10", level: "expert", desc: "Function returning void but returns value.", bug: "function log(msg: string): void {\n  return msg;\n}\nconsole.log(log('test'));", solution: "function log(msg: string): void {\n  console.log(msg);\n}\nlog('test');", test: "true // TS void" },
        { title: "Fix Fix Any vs Unknown 10", level: "expert", desc: "Using any instead of unknown requires type narrowing.", bug: "function safeParse(json: string): unknown {\n  return JSON.parse(json);\n}\nconst data = safeParse('{\"a\":1}');\nconsole.log(data.a);", solution: "function safeParse(json: string): unknown {\n  return JSON.parse(json);\n}\nconst data = safeParse('{\"a\":1}') as Record<string, any>;\nconsole.log(data.a);", test: "true // TS unknown" }
